; ========================================
; PROGRAM TERMINATION
; ========================================
exit_program:
    ; Cleanup all systems
    call cleanup_ide_systems
    
    ; Disconnect from X server
    mov rdi, [conn_ptr]
    call xcb_disconnect
    
    ; Exit program
    mov rax, 60  ; SYS_exit
    xor rdi, rdi
    syscall

cleanup_ide_systems:
    ; Cleanup all IDE systems
    ; TODO: Implement cleanup
    ret

